const plugin = require('tailwindcss/plugin')
const defaultConfig = require('./defaultConfig')

/**
 * Semantic colors, transcribed from the "Semantic Colors" grid in the Breeze
 * Figma UI Kit, which is the source of truth:
 * https://www.figma.com/design/eCz76rIWoNTtc6EiMjWxCn/Breeze---Design-System?node-id=1438-12591
 *
 * Class names mirror that grid exactly: `{column}-{row}`. The Warning row of
 * the Text column is `text-warning`, the Success row of the Border Hover
 * column is `border-hover-success`.
 *
 * Cells hold a reference to a base color in defaultConfig.js, never a literal,
 * so a change to the base scale flows through here on its own and a value only
 * ever lives in one place.
 *
 * Prefer these over a numbered base color (`text-warning`, not
 * `text-warning-800`) so intent survives a palette change, and so a design
 * that says "warning text" translates to code without anyone having to know
 * which step that maps to.
 */

// Columns of the grid, and the CSS property each one sets.
const COLUMNS = [
  ['text', 'color'],
  ['text-link', 'color'],
  ['icon', 'color'],
  ['icon-hover', 'color'],
  ['border', 'borderColor'],
  ['border-hover', 'borderColor'],
  ['background', 'backgroundColor'],
]

// Rows of the grid, values in COLUMNS order. `null` is a blank cell in Figma.
// prettier-ignore
const ROWS = {
  //             text                text-link       icon                 icon-hover           border               border-hover         background
  normal:       ['neutral-900',      'primary-700',  'neutral-800',       'neutral-900',       'neutral-200',       'neutral-300',       'white-100'],
  muted:        ['muted-500',        null,           'muted-500',         'muted-600',         'muted-300',         'muted-400',         'muted-100'],
  disabled:     ['neutral-600',      null,           'neutral-500',       null,                'neutral-100',       null,                'neutral-100'],
  primary:      ['primary-600',      null,           'primary-500',       'primary-600',       'primary-400',       'primary-500',       'primary-100'],
  secondary:    ['secondary-600',    null,           'secondary-500',     'secondary-600',     'secondary-300',     'secondary-400',     'secondary-100'],
  info:         ['info-800',         null,           'info-600',          'info-700',          'info-300',          'info-400',          'info-100'],
  success:      ['success-700',      null,           'success-600',       'success-700',       'success-300',       'success-400',       'success-100'],
  warning:      ['warning-800',      null,           'warning-800',       'warning-900',       'warning-300',       'warning-400',       'warning-100'],
  error:        ['error-700',        null,           'error-500',         'error-700',         'error-300',         'error-400',         'error-100'],
  intelligence: ['intelligence-600', null,           'intelligence-500',  'intelligence-600',  'intelligence-300',  'intelligence-400',  'intelligence-100'],
}

const colors = defaultConfig.theme.extend.colors

// References are `{family}-{step}`; families never contain a dash.
function resolve(reference) {
  const separator = reference.lastIndexOf('-')
  const value = colors[reference.slice(0, separator)]?.[
    reference.slice(separator + 1)
  ]

  if (!value) {
    throw new Error(`Unknown base color "${reference}" in semantic colors`)
  }

  return value
}

const semanticColorUtilities = Object.entries(ROWS).reduce(
  (utilities, [row, cells]) => {
    COLUMNS.forEach(([column, property], index) => {
      if (cells[index] === null) {
        return
      }

      utilities[`.${column}-${row}`] = { [property]: resolve(cells[index]) }
    })

    return utilities
  },
  {},
)

module.exports = plugin(function ({ addUtilities }) {
  addUtilities(semanticColorUtilities)
})

module.exports.semanticColorUtilities = semanticColorUtilities
