import type { Meta, StoryObj } from '@storybook/react'
import React, { Fragment } from 'react'
import tailwindColors from 'tailwindcss/colors'
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import defaultConfig from '../../defaultConfig'
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { semanticColorUtilities } from '../../semanticColorsPlugin'
import Tooltip from '../Tooltip/Tooltip'
import Typography from '../Typography/Typography'

const meta: Meta = {
  title: 'Customizations/Colors',
  parameters: {
    layout: 'padded',
  },
}

export default meta

type ThemeColor = string | Record<string, string>

type Color = { className: string; value: string | null; note?: string }

type ColorGroup = {
  name: string
  colors: Array<Color>
}

const SWATCH = 'aspect-square w-full h-14 rounded-sm outline-none sm:rounded-md'

const titleCase = (value: string) =>
  value
    .split(/[\s-]/)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ')

const getColorGroups = (
  themeColors: Record<string, ThemeColor>,
  shades?: string[],
  annotate?: (value: string) => string,
): ColorGroup[] =>
  Object.keys(themeColors).map((color) => {
    const colors = themeColors[color] as ThemeColor

    return {
      name: titleCase(color),
      colors:
        typeof colors === 'string'
          ? [{ className: `bg-${color}`, value: colors }]
          : (shades ?? Object.keys(colors)).map((shade) => ({
              className: `bg-${color}-${shade}`,
              value: colors[shade] ?? null,
              note: colors[shade] ? annotate?.(colors[shade]) : undefined,
            })),
    }
  })

function ColorGrid({
  colorGroups,
  columns,
}: {
  colorGroups: ColorGroup[]
  columns: Array<string | number>
}) {
  const templateColumns = {
    gridTemplateColumns: `repeat(${columns.length}, minmax(0, 1fr))`,
  }

  return (
    <div className="grid grid-cols-[auto_minmax(0,1fr)] items-center gap-4">
      <div></div>
      <div
        className="col-start-2 grid grid-rows-1 justify-items-center gap-1.5"
        style={templateColumns}
      >
        {columns.map((column) => (
          <div key={column}>{column}</div>
        ))}
      </div>
      {colorGroups.map((group) => (
        <Fragment key={group.name}>
          <Typography>{group.name}</Typography>
          <div className="grid gap-1.5" style={templateColumns}>
            {group.colors.map((color) =>
              color.value === null ? (
                <Tooltip
                  key={color.className}
                  title={`${color.className}: not defined`}
                >
                  <div
                    className={`${SWATCH} border border-dashed border-neutral-300`}
                  />
                </Tooltip>
              ) : (
                <Tooltip
                  key={color.className}
                  title={`${color.className}: ${color.value}${
                    color.note ? ` · ${color.note}` : ''
                  }`}
                >
                  <div
                    className={SWATCH}
                    style={{ backgroundColor: color.value }}
                  />
                </Tooltip>
              ),
            )}
          </div>
        </Fragment>
      ))}
    </div>
  )
}

const visualizationColors = {
  categorical: defaultConfig.theme.extend.colors.categorical,
  sequential: defaultConfig.theme.extend.colors.sequential,
  diverging: defaultConfig.theme.extend.colors.diverging,
} as Record<string, ThemeColor>

export const VisualizationColors: StoryObj = {
  // eslint-disable-next-line react/display-name
  render: () => (
    <ColorGrid
      colorGroups={getColorGroups(visualizationColors)}
      columns={Array.from({ length: 15 }, (_, i) => i + 1)}
    />
  ),
  tags: ['!dev'],
}

// Layer 1. Tailwind's own ramps, available because tailwind.config.js extends
// rather than replaces the default theme. Renamed aliases are skipped: reading
// them logs a deprecation warning.
const RENAMED_TAILWIND_COLORS = [
  'lightBlue',
  'warmGray',
  'trueGray',
  'coolGray',
  'blueGray',
]

const PALETTE_SHADES = [
  '50',
  '100',
  '200',
  '300',
  '400',
  '500',
  '600',
  '700',
  '800',
  '900',
  '950',
]

const tailwindRamps = Object.keys(tailwindColors).filter(
  (name) =>
    !RENAMED_TAILWIND_COLORS.includes(name) &&
    typeof tailwindColors[name as keyof typeof tailwindColors] === 'object',
)

const byHex = (
  entries: Array<[string, Record<string, string>]>,
  shades?: string[],
) =>
  entries.reduce<Record<string, string>>((lookup, [name, values]) => {
    ;(shades ?? Object.keys(values)).forEach((shade) => {
      const hex = values[shade]?.toLowerCase()

      if (hex && !(hex in lookup)) {
        lookup[hex] = `${name}-${shade}`
      }
    })

    return lookup
  }, {})

const tailwindByHex = byHex(
  tailwindRamps.map((name) => [
    name,
    tailwindColors[name as keyof typeof tailwindColors] as Record<
      string,
      string
    >,
  ]),
)

// Layer 2. The named families in defaultConfig.js, identified by the numbered
// steps the semantic layer is built from. Same 50-950 ramp as the palette:
// every family but primary and muted is a Tailwind ramp verbatim.
const BASE_SHADES = PALETTE_SHADES

const baseColors = Object.entries(
  defaultConfig.theme.extend.colors as Record<string, ThemeColor>,
).reduce<Record<string, ThemeColor>>((colors, [name, value]) => {
  if (typeof value === 'object' && '600' in value) {
    colors[name] = value
  }

  return colors
}, {})

const baseByHex = byHex(
  Object.entries(baseColors) as Array<[string, Record<string, string>]>,
  BASE_SHADES,
)

// Only the ramps a base colour is actually drawn from. Breeze extends rather
// than replaces Tailwind's theme, so the other ramps still resolve as classes
// — they just aren't part of the design system.
const paletteColors = tailwindRamps
  .filter((name) =>
    Object.values(
      tailwindColors[name as keyof typeof tailwindColors] as Record<
        string,
        string
      >,
    ).some((hex) => baseByHex[hex.toLowerCase()]),
  )
  .reduce<Record<string, ThemeColor>>((colors, name) => {
    colors[name] = tailwindColors[
      name as keyof typeof tailwindColors
    ] as ThemeColor

    return colors
  }, {})

export const PaletteColors: StoryObj = {
  // eslint-disable-next-line react/display-name
  render: () => (
    <ColorGrid
      colorGroups={getColorGroups(
        paletteColors,
        PALETTE_SHADES,
        (value) => baseByHex[value.toLowerCase()],
      )}
      columns={PALETTE_SHADES}
    />
  ),
  tags: ['!dev'],
}

export const BaseColors: StoryObj = {
  // eslint-disable-next-line react/display-name
  render: () => (
    <ColorGrid
      colorGroups={getColorGroups(
        baseColors,
        BASE_SHADES,
        (value) =>
          tailwindByHex[value.toLowerCase()] ?? 'no Tailwind 3.4 equivalent',
      )}
      columns={BASE_SHADES}
    />
  ),
  tags: ['!dev'],
}

// Layer 3. Values come from semanticColorsPlugin.js so this table cannot drift
// from the CSS it documents; the row and column order below mirrors the
// Semantic Colors grid in the Figma UI Kit.
const SEMANTIC_COLUMNS = [
  ['Text', 'text'],
  ['Text Link', 'text-link'],
  ['Icon', 'icon'],
  ['Icon Hover', 'icon-hover'],
  ['Border', 'border'],
  ['Border Hover', 'border-hover'],
  ['Background', 'background'],
]

const SEMANTIC_ROWS = [
  'normal',
  'muted',
  'disabled',
  'primary',
  'secondary',
  'info',
  'success',
  'warning',
  'error',
  'intelligence',
]

const semanticColorGroups: ColorGroup[] = SEMANTIC_ROWS.map((row) => ({
  name: titleCase(row),
  colors: SEMANTIC_COLUMNS.map(([, prefix]) => {
    const className = `${prefix}-${row}`
    const declaration = semanticColorUtilities[`.${className}`]

    const value = declaration ? (Object.values(declaration)[0] as string) : null

    return {
      className,
      value,
      note: value
        ? baseByHex[value.toLowerCase()] ?? 'no base equivalent'
        : undefined,
    }
  }),
}))

export const SemanticColors: StoryObj = {
  // eslint-disable-next-line react/display-name
  render: () => (
    <ColorGrid
      colorGroups={semanticColorGroups}
      columns={SEMANTIC_COLUMNS.map(([label]) => label)}
    />
  ),
  tags: ['!dev'],
}
